const carryText = (areas) => 'CARRY-OVER FINDINGS from the last review of the INSTALLED holes (round 3 of the previous run; the user wants them finished in THIS run too: fix every medium one and the cheap lows that are yours; the gate BASALT_JOINTS must PASS this run: glow in a branching Voronoi/hex joint network with horizontal ledges and diagonal cracks, vertical-line share <= 80%, junction density >= 3 per 100 skeleton px, never relax the gate): ' + JSON.stringify(CARRY_ALL.filter((f) => areas.includes(f.area)))

const GRASS_TEXTURE = `AREA T - GRASS TEXTURES (requirement 2). You own blender/scripts/golf_look_textures.py, the Look PNGs (Fairway_C, Fairway_N, Green_C, Green_N, Rough_C, Rough_N only; all others byte-identical), work/postcard-look/TEXTURES.md, work/postcard-look/v2/tex/, and ONLY the Fairway/Green/Rough rows + the smoothness-channel keyword handling in Unity/Assets/Scripts/Course/GolfLook.cs, and Unity/Assets/Editor/GolfLookTextureImporter.cs if the PNG format changes (the sway-shader agent also edits GolfLook.cs, in the LK_PLANTS mapping only: re-read the file before every edit and stay out of its lines). Stronger mow bands (+-12%), per-band sheen via smoothness-in-albedo-alpha (or an equally cheap texture-side equivalent; if a PNG becomes RGBA keep seamless tiling and byte-determinism), blade-lean streaks in the normal maps. Measure in the Game view through the probe/stills wrappers (v2/runtime/run_*.sh, v2/calibrate/tools/run_probe.sh; always heavy.sh; verify the textured swap took effect): hue 64-73, clipping 0, lower-60% luminance sd up vs the round-1 stills, bands visibly different in sheen at the phone camera angle. Folder <= 25 MB, generator gates and GolfLookSmoke passing. Do not rebuild holes.`

const GRASS_PROPS = `AREA P - TUFT LIBRARY + SWAY DATA (requirements 1 and 3a). You own blender/scripts/postcard_props_lib.py, postcard_props_smoke.py, Plants_C.png, work/postcard-look/LIB_PROPS.md, work/postcard-look/v2/props/, and the colors_type handling inside postcard_look_lib.export_look_fbx (that one function only; the ground-lib agent is not running now). (a) 2-3 NEW taller standing tuft variants (curved/leaning blade clumps <= 120 faces) plus a cheaper <= 40-face filler tuft, same shared LK_PLANTS palette (existing meshes stay byte-compatible). (b) A fringe scatter helper: density falloff outward from the fairway/green/pad-rim/path/shore-lip edge, clump clustering (3-7 plus singles), per-instance lean +-12 degrees and 0.6-1.8x height variation, exclusion masks (Fairway/Green/Bunker/Tee outlines, water, ball-address zones as (x,y,radius) list, pin clearance), deterministic seeds, triangle accounting returned so hole scripts stay <= 250k. (c) SWAY DATA on EVERY PLANT_* library mesh (tufts, shrubs, flowers, vines, agave, trees/pines): vertex colour attribute per requirement 3 (R weight, G phase), authored by shape (tufts/flowers/agave tip-weighted by height, shrubs small, vines pinned at the attach point increasing downward, pine/tree small), verified surviving export_look_fbx -> FBX -> Blender re-import (and, with the Unity agent, Unity mesh.colors). (d) documented API + examples in LIB_PROPS.md, smoke + gates (face budgets, mask tests on the three real hole designs, 0 footprint rays on water or play surfaces, PLANT_SWAY_COLORS, mutants), previews. Do not edit hole scripts.`

const GRASS_SWAY = `AREA U - SWAY SHADER + WIND DRIVER + GATES (requirement 3b). You own Unity/Assets/Resources/Course/Shaders/GolfPlants.shader (new), Unity/Assets/Scripts/Course/GolfWindSway.cs (new) and its meta files, the LK_PLANTS mapping in Unity/Assets/Scripts/Course/GolfLook.cs (re-read before each edit: the texture agent edits the Fairway/Green/Rough rows), the minimal Wind hook in Unity/Assets/Scripts/Game/GolfGame.cs, GolfLookSmoke.cs, PostcardLookStills.cs (add a documented freeze-time + fixed-wind option for deterministic sway frame pairs), PostcardImportCheck.cs, RUNTIME.md, and blender/scripts/postcard_look_verify.py + GATES.md (add PLANT_SWAY_COLORS and keep every existing gate; mutants must FAIL; the tool's 'static shader' check must allow time use ONLY in GolfPlants.shader/GolfWindSway and still forbid it in the lava/surf/fall/sky/water paths). Implement requirement 3 exactly (world-space vertex displacement by vertex-colour weight, per-instance phase, wind-driven, caps, ShadowCaster + DepthOnly with the same sway, instancing + SRP Batcher compatible, Metal-safe). Wind plumbing: GolfWindSway reads GolfGame.Wind (speed mph, direction degrees right of +D => world direction (sin d, 0, cos d)) and sets the global shader values each frame; hole start sets the hole's wind; no per-frame allocations. Verify through heavy.sh: compile 0 errors, GolfLookSmoke (material uses GolfArcade/GolfPlants, texture + tint + smoothness unchanged), a C# or editor-side mirror of the displacement function to MEASURE max displacement per kind at 0/10/20 mph vs the caps, Game-view frame pairs on the current installed holes (plants move, nothing else does; until the new plant meshes with sway colours are installed the existing plants have no colours: treat colour-less meshes as weight 0 = static and say so), determinism with the freeze override, hole 7 byte-identical. Not measurable here: a physical iOS device frame time: say so, and keep the vertex cost minimal.`

const GRASS_HOLE = (h) => [{ severity: 'high', hole: h, area: 'hole_script', user_line: 'GRASS LIVELINESS + SWAY: the near ground reads as a carpet; add the edge fringe; plants must carry sway data', where: 'blender/scripts/hole' + h + '_look.py (and hole' + h + '_build.py if needed)', evidence: 'Round-1 Game-view stills: tee/approach lower 60% grass is uniform; tufts exist only as a thin scatter; plants are static.', fix_hint: 'Use the new tuft variants + fringe scatter helper in postcard_props_lib.py (read LIB_PROPS.md) along the rough edge of the fairway/green/pad rims, path edges (Needle), shore tops and cliff lips; ball-address zones come from work/postcard-look/v2/hole' + h + '/landmarks.json; keep <= 250k triangles (report before/after); tuft tops <= 0.55 yd near the ball corridor; export with postcard_look_lib.export_look_fbx so every PLANT_* keeps its sway vertex colours (check the FBX re-import: PLANT_SWAY_COLORS gate); restage, re-run every hole gate, update INSTALL.md / landmarks.json / sha files.' }]

phase('Fix')
log(OPEN_STATE)
const finishRes = await parallel([
  () => agent(`${COMMON}\n\n${GRASS_TEXTURE}\n\n${carryText(['texture'])}`, { label: 'grass:T textures', phase: 'Fix', schema: RESULT }),
  () => agent(`${COMMON}\n\n${GRASS_PROPS}\n\n${carryText(['lib_props', 'lib_ground'])}\nFor the Crater pin: make the flag a saturated white or red cloth at least 6x10 px at approach range, clear of the dark wall; round/taper the pillar underside below the frozen top outline (scoring-neutral).`, { label: 'grass:P tuft lib + sway data', phase: 'Fix', schema: RESULT }),
  () => agent(`${COMMON}\n\n${GRASS_SWAY}\n\n${carryText(['unity_runtime', 'gate_tool'])}`, { label: 'grass:U sway shader + driver', phase: 'Fix', schema: RESULT }),
])
history.push({ round: -1, finishRes })
log('grass fix: ' + finishRes.map((r, i) => ['T', 'P', 'U'][i] + ' ' + (r ? r.status + ' fails=' + r.gates.filter((g) => !g.pass).map((g) => g.id).join(',') : 'NO RESULT')).join(' | '))

phase('Rebuild')
const rebuildRes = await parallel(HOLES.map((h) => () => agent(holeFixPrompt(h, GRASS_HOLE(h).concat(CARRY_ALL.filter((f) => (f.hole === h || f.hole === 'all') && (f.area === 'hole_script' || f.area === 'other'))), 0), { label: 'grass:hole ' + h, phase: 'Rebuild', schema: RESULT })))
history.push({ round: -1, rebuildRes })
log('grass holes: ' + rebuildRes.map((r, i) => HOLES[i] + ' ' + (r ? r.status + ' fails=' + r.gates.filter((g) => !g.pass).map((g) => g.id).join(',') : 'NO RESULT')).join(' | '))

phase('Install')
let integ = await agent(`${COMMON}\n\n${INTEGRATE}`, { label: 'install:I round0', phase: 'Install', schema: RESULT })
history.push({ round: 0, integ })

phase('Review')
let panel = await reviewPanel(0, null)
log('round 0 review: 08 ' + summarize(panel['08']) + ' | 09 ' + summarize(panel['09']) + ' | 10 ' + summarize(panel['10']) + ' | gates ' + summarize(panel.gates))
history.push({ round: 0, panel })

function allPass(p) {
  return ['08', '09', '10', 'gates'].every((k) => p[k] && p[k].verdict === 'PASS')
}

for (let round = 1; round <= 3 && !allPass(panel); round++) {
  phase('Repair')
  const all = []
  for (const k of ['08', '09', '10', 'gates']) {
    if (panel[k]) for (const f of panel[k].findings) if (f.severity !== 'low' || panel[k].verdict === 'FAIL') all.push(f)
  }
  const sharedAreas = { texture: 'texture', lib_ground: 'libs', lib_props: 'libs', unity_runtime: 'unity', gate_tool: 'unity' }
  const groups = {}
  for (const f of all) {
    const g = sharedAreas[f.area]
    if (g) (groups[g] = groups[g] || []).push(f)
  }
  const gk = Object.keys(groups)
  log('round ' + round + ' shared repair groups: ' + (gk.join(', ') || 'none'))
  const sharedRes = gk.length
    ? await parallel(gk.map((g) => () => agent(sharedFixPrompt(g, groups[g], round), { label: 'fix' + round + ':shared ' + g, phase: 'Repair', schema: RESULT })))
    : []
  // hole fixers: all findings that are hole_script/other for that hole, plus 'all' hole ones
  const holeItems = {}
  for (const h of HOLES) holeItems[h] = all.filter((f) => (f.hole === h || f.hole === 'all') && (f.area === 'hole_script' || f.area === 'other'))
  const needsRebuild = gk.includes('libs') || gk.includes('texture')
  const holeRes = await parallel(HOLES.filter((h) => holeItems[h].length > 0 || needsRebuild).map((h) => () => agent(holeFixPrompt(h, holeItems[h], round), { label: 'fix' + round + ':hole ' + h, phase: 'Repair', schema: RESULT })))
  history.push({ round, sharedRes, holeRes })
  phase('Install')
  integ = await agent(`${COMMON}\n\nThis is repair round ${round}. The installer script work/postcard-look/v2/proof/run_proof.sh from round 0 exists: re-run it (it reinstalls changed staged files, re-runs Unity checks, re-shoots the 9 stills, and re-measures); fix the script if the stage layout changed. If a hole was rebuilt after the libs changed, make sure you install the NEW stage.\n\n${INTEGRATE}`, { label: 'install:I round' + round, phase: 'Install', schema: RESULT })
  phase('Review')
  panel = await reviewPanel(round, { '08': panel['08'] && panel['08'].findings, '09': panel['09'] && panel['09'].findings, '10': panel['10'] && panel['10'].findings, gates: panel.gates && panel.gates.findings })
  log('round ' + round + ' review: 08 ' + summarize(panel['08']) + ' | 09 ' + summarize(panel['09']) + ' | 10 ' + summarize(panel['10']) + ' | gates ' + summarize(panel.gates))
  history.push({ round, integ, panel })
}

return { allPass: allPass(panel), finalPanel: panel, finalInstall: integ, rounds: history.length }
